        return []

    n = len(grid)
    m = len(grid[0])

    # Mark cells reachable from the border without crossing any 2
    visited = [[False] * m for _ in range(n)]
    q = deque()

    # Initialize queue with all border cells that are not 2
    for i in range(n):
        for j in range(m):
            if i == 0 or i == n - 1 or j == 0 or j == m - 1:
                if grid[i][j] != 2:
                    visited[i][j] = True
                    q.append((i, j))

    # BFS traversal
    while q:
        i, j = q.popleft()
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and not visited[ni][nj] and grid[ni][nj] != 2:
