                q.append((ni, nj))

    # Create output grid and fill interior zeros with 1
    out = [row[:] for row in grid]
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 0 and not visited[i][j]:
                out[i][j] = 1

    return out

